#!/usr/bin/python3
from pwn import *

def test_sizes():
    sizes = [8, 24, 32, 64, 128, 0x200, 0x500]

    for size in sizes:
        p = process('/home/ctfplayer/ctf_files/popping_caps')
        log.info(f"Testing size: {hex(size)}")

        p.sendlineafter(b"choice: ", b"1")
        p.sendlineafter(b"many: ", str(size).encode())
        output = p.recvuntil(b"BANG!", timeout=1)

        if output:
            log.success(f"Malloc size {hex(size)} succeeded")
        else:
            log.failure(f"Malloc size {hex(size)} failed")

        p.close()

test_sizes()

